{"path": "task/workspace/data/binding/sprintf.go", "start": 1, "lines": 95, "offset": 0, "total_lines": 95, "content": "package binding

import (
	"fmt"
)

// StringFormat is a String binding that formats its value using fmt.Sprintf when read.
// The binding monitors source items and reformats when any changes.
//
// Since: 2.5
type StringFormat interface {
	String
}

type stringFormat struct {
	base

	format  string
	sources []DataItem
}

// NewStringFormat returns a new String binding that formats a value using the provided
// fmt.Sprintf format string and source bindings. When any source changes, the formatted
// result is recalculated and listeners are notified.
//
// Example:
//   name := binding.NewString()
//   name.Set("Alice")
//   age := binding.NewInt()
//   age.Set(30)
//   formatted := binding.NewStringFormat("Name: %s, Age: %d", name, age)
//   val, _ := formatted.Get() // Returns "Name: Alice, Age: 30"
//
// Since: 2.5
func NewStringFormat(format string, sources ...DataItem) StringFormat {
	s := &stringFormat{
		format:  format,
		sources: sources,
	}

	// Listen to all sources
	listener := NewDataListener(func() {
		s.lock.Lock()
		defer s.lock.Unlock()
		s.trigger()
	})

	for _, source := range sources {
		source.AddListener(listener)
	}

	return s
}

func (s *stringFormat) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	// Gather values from all sources
	values := make([]interface{}, len(s.sources))
	for i, source := range s.sources {
		// Try to get the value from the source
		val, err := s.getValue(source)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	// Format using fmt.Sprintf
	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFormat) Set(string) error {
	// StringFormat is read-only, it derives its value from sources
	return fmt.Errorf("cannot set value on a formatted string binding")
}

// getValue attempts to extract a value from a DataItem
func (s *stringFormat) getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case String:
		return v.Get()
	case Bool:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case Untyped:
		return v.Get()
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
