{"path": "task/workspace/data/binding/sprintf.go", "start": 1, "lines": 199, "offset": 0, "total_lines": 199, "content": "package binding

import (
	"fmt"

	"fyne.io/fyne/v2/storage"
)

// StringFormat is a String binding that formats its value using fmt.Sprintf when read.
// The binding monitors source items and reformats when any changes.
// It can also parse back using fmt.Sscanf when Set() is called.
//
// Since: 2.5
type StringFormat interface {
	String
}

type stringFormat struct {
	base

	format  string
	sources []DataItem
}

// NewSprintf returns a new String binding that formats a value using 
// fmt.Sprintf with the specified format string and source data bindings.
// When Get() is called, it formats using the current source values.
// When Set() is called, it parses using fmt.Sscanf and updates source bindings.
//
// Since: 2.5
func NewSprintf(format string, b ...DataItem) String {
	if len(b) == 0 {
		return NewString("") // Empty binding if no sources
	}

	s := &stringFormat{
		format:  format,
		sources: b,
	}

	// Listen to all source bindings
	for _, item := range b {
		item.AddListener(s)
	}

	return s
}

// StringToStringWithFormat creates a new String binding that reformats 
// another String binding using the specified format string.
// This is a convenience function for NewSprintf with a single String source.
//
// Since: 2.5
func StringToStringWithFormat(str String, format string) String {
	return NewSprintf(format, str)
}

func (s *stringFormat) Get() (string, error) {
	values := make([]interface{}, len(s.sources))

	for i, item := range s.sources {
		val, err := s.getValue(item)
		if err != nil {
			return "", err
		}
		values[i] = val
	}

	return fmt.Sprintf(s.format, values...), nil
}

func (s *stringFormat) Set(val string) error {
	// Parse the formatted string back using Sscanf
	values := make([]interface{}, len(s.sources))

	// Create pointers for Sscanf to write into
	for i, item := range s.sources {
		switch item.(type) {
		case String:
			var v string
			values[i] = &v
		case Bool:
			var v bool
			values[i] = &v
		case Float:
			var v float64
			values[i] = &v
		case Int:
			var v int
			values[i] = &v
		case Bytes:
			return fmt.Errorf("cannot parse into Bytes binding")
		case Rune:
			var v rune
			values[i] = &v
		case URI:
			var v string
			values[i] = &v
		case Untyped:
			var v interface{}
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type: %T", item)
		}
	}

	// Parse the string
	n, err := fmt.Sscanf(val, s.format, values...)
	if err != nil {
		return fmt.Errorf("failed to parse format: %w", err)
	}
	if n != len(s.sources) {
		return fmt.Errorf("format matched %d items, expected %d", n, len(s.sources))
	}

	// Set the parsed values back to source bindings
	for i, item := range s.sources {
		switch v := item.(type) {
		case String:
			if err := v.Set(*values[i].(*string)); err != nil {
				return err
			}
		case Bool:
			if err := v.Set(*values[i].(*bool)); err != nil {
				return err
			}
		case Float:
			if err := v.Set(*values[i].(*float64)); err != nil {
				return err
			}
		case Int:
			if err := v.Set(*values[i].(*int)); err != nil {
				return err
			}
		case Rune:
			if err := v.Set(*values[i].(*rune)); err != nil {
				return err
			}
		case URI:
			uri, err := storage.ParseURI(*values[i].(*string))
			if err != nil {
				return fmt.Errorf("failed to parse URI: %w", err)
			}
			if err := v.Set(uri); err != nil {
				return err
			}
		case Untyped:
			if err := v.Set(*values[i].(*interface{})); err != nil {
				return err
			}
		}
	}

	s.trigger()
	return nil
}

// AddListener attaches a new change listener to this binding
func (s *stringFormat) AddListener(listener DataListener) {
	s.base.AddListener(listener)
}

// RemoveListener detaches a change listener from this binding
func (s *stringFormat) RemoveListener(listener DataListener) {
	s.base.RemoveListener(listener)
}

// DataChanged is called when a source binding changes
func (s *stringFormat) DataChanged() {
	s.trigger()
}

// getValue attempts to extract a value from a DataItem
func (s *stringFormat) getValue(item DataItem) (interface{}, error) {
	switch v := item.(type) {
	case String:
		return v.Get()
	case Bool:
		return v.Get()
	case Float:
		return v.Get()
	case Int:
		return v.Get()
	case Bytes:
		return v.Get()
	case Rune:
		return v.Get()
	case URI:
		uri, err := v.Get()
		if err != nil {
			return nil, err
		}
		return uri.String(), nil
	case Untyped:
		return v.Get()
	default:
		return nil, fmt.Errorf("unsupported binding type: %T", item)
	}
}
